import assert from 'node:assert/strict';
import { readFile, mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
const [reportPath, dev] = process.argv.slice(2);
const report = JSON.parse(await readFile(reportPath,'utf8'));
const {createOutputValidator} = await import(pathToFileURL(join(dev,'src/output-schema.ts')).href);
const {prepareExecutionPlan} = await import(pathToFileURL(join(dev,'src/execution-plan.ts')).href);
const root = await mkdtemp('/tmp/r08-corpus-fixture-');
let goldenCount=0, negativeCount=0, planCount=0, checkCount=0, semanticMismatchAccepted=0;
const validators=Object.fromEntries(Object.entries(report.corpus.outputSchemas).map(([role,schema])=>[role,createOutputValidator(schema)]));
const hashes = content => createHash('sha256').update(content).digest('hex');
try {
 for(const item of report.corpus.cases){
  const validate=validators[item.role];
  assert.deepEqual(validate(item.golden),item.golden); goldenCount++;
  for(const value of [{...item.golden,unexpected:true},{...item.golden,decision:'not-a-decision'},Object.fromEntries(Object.entries(item.golden).filter(([k])=>k!=='evidence'))]){
   assert.throws(()=>validate(value)); negativeCount++;
  }
  const cwd=join(root,item.id); await mkdir(cwd,{recursive:true});
  for(const [path,body] of Object.entries(item.files)){
   assert.ok(resolve(cwd,path).startsWith(cwd+'/')); await mkdir(dirname(join(cwd,path)),{recursive:true}); await writeFile(join(cwd,path),body);
  }
  const skillDir=join(cwd,'eval-skill');
  for(const [path,body] of Object.entries(report.corpus.skillBundles[item.skillBundle])){
   await mkdir(dirname(join(skillDir,path)),{recursive:true}); await writeFile(join(skillDir,path),body);
  }
  const protectedBefore=Object.fromEntries(await Promise.all(item.protectedFiles.map(async path=>[path,hashes(await readFile(join(cwd,path)))])));
  for(const check of item.fixtureChecks){
   assert.equal(check.command,'node'); assert.deepEqual(check.args,['checks/check.mjs']);
   const result=spawnSync(process.execPath,check.args,{cwd,encoding:'utf8'});
   assert.equal(result.status,check.expectedExitCode); assert.ok(result.stdout.includes(check.stdoutIncludes)); checkCount++;
  }
  for(const path of item.protectedFiles) assert.equal(hashes(await readFile(join(cwd,path))),protectedBefore[path]);
  for(const arm of ['D','S']){
   const config={outputSchema:report.corpus.outputSchemas[item.role],skills:arm==='S'?['eval-skill']:[]};
   const task=item.task+(arm==='D'?'\n'+report.corpus.skillBundles[item.role]['references/procedure.md']:'\nПримени выбранный skill r08-'+item.role);
   const workflow={schemaVersion:1,id:'r08-corpus',name:'Offline corpus',revision:1,entryGraph:'main',graphs:{main:{entry:'work',nodes:[{id:'work',kind:'agent',role:item.role,task:{op:'literal',value:task},input:{op:'literal',value:item.input},config},{id:'done',kind:'end',value:{op:'ref',path:['nodes','work']}}],edges:[{from:'work',to:'done'}]}}};
   const plan=await prepareExecutionPlan(workflow,{cwd,availableModels:[{provider:'offline-test',id:'fixture',thinkingLevels:['off','medium','high']}]});
   assert.equal(plan.agents.main.work.skills.length,arm==='S'?1:0); planCount++;
  }
 }
 // A semantic lie can have the correct schema. This must be scored outside Ajv.
 const wrong=structuredClone(report.corpus.cases.find(x=>x.id==='R08-G1').golden);wrong.total=999;
 validators.general(wrong);semanticMismatchAccepted++;
 console.log(JSON.stringify({schemaCount:Object.keys(validators).length,goldenCount,negativeCount,planCount,fixtureCheckCount:checkCount,semanticMismatchAccepted,modelCalls:0},null,2));
} finally {await rm(root,{recursive:true,force:true});}

