// Read-only artifact audit. No models, SDK sessions, fixture commands, or plan preparation.
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { isAbsolute, join } from 'node:path';
import { pathToFileURL } from 'node:url';
const [reportPath, study, dev] = process.argv.slice(2);
const report = JSON.parse(await readFile(reportPath, 'utf8'));
for (const p of ['src/catalog.ts','src/output-schema.ts']) {
  assert.deepEqual(await readFile(join(study,p)), await readFile(join(dev,p)), p + ' must match study bytes');
}
const {resolveAgentConfig} = await import(pathToFileURL(join(dev,'src/catalog.ts')).href);
const {createOutputValidator} = await import(pathToFileURL(join(dev,'src/output-schema.ts')).href);
const unique = (xs, label) => assert.equal(new Set(xs).size, xs.length, label);
const safe = p => assert.ok(!isAbsolute(p) && p.split('/').every(x => x && x !== '.' && x !== '..') && !p.includes('\\'), p);
unique(report.findings.map(x=>x.id),'findings');
unique(report.experiments.map(x=>x.id),'experiments');
unique(report.sources.map(x=>x.id),'sources');
unique(report.corpus.cases.map(x=>x.id),'cases');
assert.equal(report.summary.findingCount,report.findings.length);
assert.equal(report.summary.confirmedBugCount,report.findings.filter(x=>x.classification==='bug').length);
assert.equal(report.corpus.caseCount,report.corpus.cases.length);
const sourceIds = new Set(report.sources.map(x=>x.id));
const experimentIds = new Set(report.experiments.map(x=>x.id));
for(const f of report.findings) {
  assert.ok(['bug','idea','unknown','already-fixed'].includes(f.classification));
  f.evidence.forEach(id=>assert.ok(sourceIds.has(id),id));
  f.experiments.forEach(id=>assert.ok(experimentIds.has(id),id));
}
for(const s of report.sources) {
  const text = await readFile(join(s.path.startsWith('node_modules/')?dev:study,s.path),'utf8');
  const lines = text.split('\n'); if(lines.at(-1)==='') lines.pop();
  for(const range of s.lines.split(',')) {
    const values = range.split('-').map(Number); const lo = values[0], hi = values.at(-1);
    assert.ok(1<=lo && lo<=hi && hi<=lines.length, s.id+' '+s.lines);
  }
}
for(const r of report.coverage.roles) {
  const actual = resolveAgentConfig(r.name);
  for(const key of ['permission','tools','skills','session','outputRepair']) assert.deepEqual(r[key],actual[key],r.name+'/'+key);
  assert.equal(r.thinkingDefault,actual.thinking);
  assert.equal(r.roleSpecificOutputSchema,actual.outputSchema!==undefined);
  assert.ok(actual.systemPrompt.endsWith('\n\n'+r.roleTail));
}
const validators = Object.fromEntries(Object.entries(report.corpus.outputSchemas).map(([k,v])=>[k,createOutputValidator(v)]));
const counts = {sources:report.sources.length,roles:report.coverage.roles.length,schemas:Object.keys(validators).length,cases:0,localProvenanceChecks:0,fixturePathChecks:0,expectedDecisionChecks:0,modelCalls:0,fixtureCommandsExecuted:0,plansPrepared:0};
for(const c of report.corpus.cases) {
  assert.ok(validators[c.outputSchema] && report.corpus.skillBundles[c.skillBundle]);
  assert.equal(c.modelExecuted,false);
  assert.deepEqual(validators[c.role](c.golden),c.golden);
  for(const key of c.oracle.exactFields) assert.ok(Object.hasOwn(c.golden,key),c.id+'/'+key);
  for(const files of [c.files,report.corpus.skillBundles[c.skillBundle]]) for(const p of Object.keys(files)) { safe(p); counts.fixturePathChecks++; }
  c.protectedFiles.forEach(p=>assert.ok(Object.hasOwn(c.files,p),p));
  c.fixtureChecks.forEach(x=>{assert.equal(x.command,'node');assert.deepEqual(x.args,['checks/check.mjs']);assert.ok(Object.hasOwn(c.files,x.args[0]));});
  const ids = c.golden.evidence.map(x=>x.id); unique(ids,c.id+' evidence');
  for(const claim of c.golden.claims??[]) for(const id of claim.evidenceIds) {assert.ok(ids.includes(id),c.id+'/'+id); counts.localProvenanceChecks++;}
  for(const conflict of c.golden.conflicts??[]) for(const id of conflict.sourceIds) {assert.ok(ids.includes(id),c.id+'/'+id); counts.localProvenanceChecks++;}
  let expected;
  if(c.role==='general') {
    const rows = JSON.parse(c.files[c.input.current]).rows.filter(x=>x.status==='posted');
    const sufficient = rows.every(x=>typeof x.unit==='string') && new Set(rows.map(x=>x.unit)).size===1;
    assert.deepEqual(c.golden.selectedIds,rows.map(x=>x.id));
    assert.equal(c.golden.total,sufficient?rows.reduce((a,x)=>a+x.amount,0):null);
    expected=sufficient?'complete':'inconclusive';
  } else if(c.role==='researcher') {
    if(['R08-R1','R08-R3'].includes(c.id)) {assert.match(c.files['current.ts'],/CURRENT_TIMEOUT = 5;/);expected='complete';}
    else if(c.id==='R08-R2') {assert.ok(!Object.hasOwn(c.files,c.input.measurementPath));expected='inconclusive';}
    else {assert.equal(new Set(JSON.parse(c.files['sources.json']).reports.map(x=>x.primaryId)).size,1);expected='inconclusive';}
  } else if(c.role==='verifier') {
    // This inspects corpus expectations, not observed command execution.
    expected=Object.hasOwn(c.files,c.input.check.args[0])?(c.fixtureChecks[0].expectedExitCode===0?'pass':'fail'):'blocked';
    assert.equal(c.golden.artifactUnchanged,true);
  } else if(c.role==='synthesizer') {
    const envelopes=Object.entries(c.input.research);
    const values=envelopes.filter(([,x])=>x.status==='succeeded').map(([,x])=>x.value);
    assert.deepEqual(c.golden.reportIds,envelopes.map(([id])=>id));
    assert.deepEqual(c.golden.failedIds,envelopes.filter(([,x])=>x.status==='failed').map(([id])=>id));
    expected=values.length===envelopes.length && values.every(x=>x.decision==='complete') && new Set(values.flatMap(x=>x.facts.map(f=>f.value))).size===1?'accepted':'inconclusive';
  } else if(c.role==='arbiter') {
    const entries=Object.entries(c.input.votes), ok=entries.filter(([,x])=>x.status==='succeeded');
    const stale=ok.filter(([,x])=>x.value.artifactRevision!==c.input.artifactRevision || x.value.acceptanceCriteriaRevision!==c.input.acceptanceCriteriaRevision);
    assert.equal(c.golden.policyId,c.input.policy??null);
    assert.equal(c.golden.artifactRevision,c.input.artifactRevision);
    assert.equal(c.golden.acceptanceCriteriaRevision,c.input.acceptanceCriteriaRevision);
    if(!c.input.policy||stale.length) expected='inconclusive';
    else if(ok.length!==entries.length) expected=ok.some(([,x])=>x.value.findings.some(f=>f.severity==='error'))?'request_changes':'inconclusive';
    else { const n=ok.filter(([,x])=>x.value.decision==='approve').length; expected=n>=(c.input.policy==='unanimous'?4:3)?'approve':ok.some(([,x])=>x.value.decision==='request_changes')?'request_changes':'inconclusive'; }
  } else if(c.role==='orchestrator') {
    const s=c.input.state;
    const next=!s.artifactRevision || (s.check.attempted && s.check.exitCode==null)?'await_evidence':!s.check.attempted?'verify':s.check.exitCode!==0?'repair':s.review?.decision==='approve' && s.review.artifactRevision===s.artifactRevision && s.review.acceptanceCriteriaRevision===s.acceptanceCriteriaRevision?'finish_accepted':'review';
    assert.equal(c.golden.next,next); assert.deepEqual(c.golden.executedActions,[]);
    expected=next==='await_evidence'?'inconclusive':'complete';
  }
  assert.equal(c.golden.decision,expected,c.id); counts.expectedDecisionChecks++; counts.cases++;
}
assert.equal(counts.cases,24);
assert.equal(report.evalPlan.status,'proposed-not-executed');
console.log(JSON.stringify({status:'pass',...counts}));
